tokens.css:
--color-bg: #fffdfb;
--color-surface: #fbf1f5;
--color-text: #2b2622;
--color-text-muted: #6e645e;
--color-border: #e2d2da;
--color-primary: #d274a3;
--color-on-primary: #2b2622;
--color-accent: #173928;
--color-on-accent: #ffffff;
--font-display: "Schibsted Grotesk", system-ui, sans-serif;
--font-body: "Schibsted Grotesk", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 17px;
--text-lg: 21px;
--text-xl: 27px;
--text-2xl: 33px;
--text-3xl: 42px;
--radius-control: 4px;
--radius-card: 12px;
--space-section: 100px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
